import type { MeasureEffectBadge, SectorMeasureCard } from '@argentina-sim/domain';

interface RawMeasureSpec {
  id: string;
  sectorId: string;
  title: string;
  description: string;
  durationType: 'TEMPORAL' | 'PERMANENTE';
  ideologyTag: 'IZQUIERDA' | 'CENTRO' | 'DERECHA';
  fiscalCostPctGdp: number;
  inflationEffectPp: number;
  approvalEffectPp: number;
  mutuallyExclusiveWith?: string;
  extraBadge?: MeasureEffectBadge;
}

function makeNumericBadge(
  label: string,
  value: number,
  decimals: number,
  positiveWhenNegative: boolean
): MeasureEffectBadge {
  const sign = value > 0 ? '+' : '';
  const isPositive = positiveWhenNegative ? value < 0 : value > 0;
  return {
    label,
    rangeText: `${sign}${value.toFixed(decimals).replace('.', ',')}`,
    isPositive
  };
}

function buildEffectsBadges(spec: RawMeasureSpec): MeasureEffectBadge[] {
  const candidates: Array<MeasureEffectBadge | null> = [
    spec.inflationEffectPp !== 0 ? makeNumericBadge('INFLACIÓN MENSUAL', spec.inflationEffectPp, 1, true) : null,
    spec.fiscalCostPctGdp !== 0 ? makeNumericBadge('GASTO PRIMARIO', spec.fiscalCostPctGdp, 2, true) : null,
    spec.approvalEffectPp !== 0 ? makeNumericBadge('APROBACIÓN', spec.approvalEffectPp, 1, false) : null,
    spec.extraBadge ?? null
  ];
  return candidates.filter((item): item is MeasureEffectBadge => item !== null);
}

function mkMeasure(spec: RawMeasureSpec): SectorMeasureCard {
  return {
    id: spec.id,
    sectorId: spec.sectorId,
    title: spec.title,
    description: spec.description,
    durationType: spec.durationType,
    frequencyLabel: spec.durationType === 'TEMPORAL' ? 'CADA 6 M.' : undefined,
    cooldownMonths: spec.durationType === 'TEMPORAL' ? 3 : undefined,
    ideologyTag: spec.ideologyTag,
    effectsBadges: buildEffectsBadges(spec),
    mutuallyExclusiveWith: spec.mutuallyExclusiveWith,
    active: false,
    fiscalCostPctGdp: spec.fiscalCostPctGdp,
    inflationEffectPp: spec.inflationEffectPp,
    approvalEffectPp: spec.approvalEffectPp
  };
}

